"use strict";

// A command state machine in mysql2's shape (lib/commands/command.js and the
// state handlers of query.js and prepare.js): every handler returns the NEXT
// handler as an unbound method read (`return this.readRow;`), and the driver
// stores it back with a plain method-style call (`this.next = this.next(...)`).
// Nothing here is typed: the parameters are untyped JavaScript, so every
// method is an implicit-any (monomorphized) member of this npm-static package.

let preCalls = 0;

class Command {
  constructor() {
    this.next = null;
    this.hits = 0;
    this.trace = "";
  }

  start(packet, conn) {
    this.trace += "start:" + packet + ",";
    return this.readRow;
  }

  readRow(packet, conn) {
    this.hits++;
    this.trace += "row:" + packet + ",";
    return packet === "end" ? null : this.readRow;
  }

  pre(packet, conn) {
    preCalls++;
    return this.hits;
  }

  execute(packet, conn) {
    if (!this.next) {
      this.next = this.start;
    }
    this.next = this.next(packet, conn);
    return this.next !== null;
  }
}

class Upper extends Command {
  readRow(packet, conn) {
    this.hits += 10;
    this.trace += "upper:" + packet + ",";
    return packet === "end" ? null : this.readRow;
  }
}

function run(kind, packets, conn) {
  const c = kind === "upper" ? new Upper() : new Command();
  let steps = 0;
  for (const p of packets) {
    steps++;
    if (!c.execute(p, conn)) break;
  }
  return steps + ":" + c.hits + ":" + c.trace;
}

function identity() {
  const b = new Command();
  const u = new Upper();
  return [
    b.readRow === Command.prototype.readRow,
    b.start === u.start,
    u.readRow === Command.prototype.readRow,
    u.readRow === Upper.prototype.readRow,
    b.readRow === b.readRow,
  ].join(",");
}

function detached(conn) {
  const f = new Command().readRow;
  try {
    f("z", conn);
    return "no throw";
  } catch (e) {
    return "threw " + (e instanceof TypeError);
  }
}

function beforeThis() {
  const f = new Command().pre;
  try {
    f("q", null);
    return "no throw";
  } catch (e) {
    return "threw " + (e instanceof TypeError) + " " + e.message + " calls " + preCalls;
  }
}

function viaCall(conn) {
  const f = new Command().readRow;
  const u = new Upper();
  return f.call(u, "c", conn) === u.readRow;
}

module.exports = { Command, Upper, run, identity, detached, viaCall, beforeThis };
